package com.nth.desktop3d;

import android.app.Instrumentation;
import android.content.Intent;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Recorded screen management, identity-safe folder movement and full menu labels. */
final class DesktopManagementSmoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;private final LauncherStore store;
    DesktopManagementSmoke(Instrumentation t,MainActivity a,String o){test=t;activity=a;output=o;store=(LauncherStore)field("store");}
    void run()throws Exception{
        LauncherStore.Item wrong=new LauncherStore.Item("folder","Accidental category collection"),target=new LauncherStore.Item("folder","Correct destination folder with a complete name"),app=new LauncherStore.Item("builtin:notes","An exceptionally long application name for folder movement");wrong.children.add(app);
        int[] pages=new int[2];main(()->{invoke("closePanel");pages[0]=store.appendPage();store.pages.get(pages[0]).add(wrong);pages[1]=store.appendPage();store.pages.get(pages[1]).add(target);store.page=pages[0];store.setHomePage(pages[0]);store.preferences.edit().putString("widget_ids_page_"+pages[1],"947").putBoolean("folder_pattern_page_"+pages[1],true).putInt("sort_undo_page",pages[1]).commit();store.save();invoke("showDesktopManager");});
        await(()->findTag("desktop-preview:"+pages[0])!=null&&findTag("desktop-preview:"+pages[0]).getWidth()>0,"Desktop miniatures missing");capture("desktop-manager-overview");
        View from=findTag("desktop-preview:"+pages[0]),to=findTag("desktop-preview:"+pages[1]);HorizontalScrollView scroll=(HorizontalScrollView)find(v->v instanceof HorizontalScrollView);int cardWidth=((View)from.getParent()).getWidth();main(()->scroll.scrollTo(pages[0]*cardWidth+cardWidth/4,0));SystemClock.sleep(500);
        int[] a=point(from),b=point(to);long time=SystemClock.uptimeMillis();pointer(time,0,a[0],a[1]);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);await(this::dragging,"Held desktop preview did not start a native drag");for(int n=1;n<=4;n++)pointer(time,2,a[0]+(b[0]-a[0])*n/4f,a[1]+(b[1]-a[1])*n/4f);pointer(time,1,b[0],b[1]);
        await(()->store.pages.get(pages[1]).contains(wrong),"Native preview drag did not reorder screens");check(store.page==pages[1]&&store.homePage()==pages[1],"Reorder moved selection or Home to the wrong screen");check(store.preferences.getString("widget_ids_page_"+pages[0],"").equals("947")&&store.preferences.getBoolean("folder_pattern_page_"+pages[0],false)&&store.preferences.getInt("sort_undo_page",-1)==pages[0],"Reorder lost widget, pattern or Undo page assignments");
        main(()->store.preferences.edit().remove("widget_ids_page_"+pages[0]).commit());capture("desktop-manager-reordered-home");
        View remove=find(v->android.text.TextUtils.equals("Remove "+store.pageName(pages[1]),v.getContentDescription()));check(remove!=null&&!remove.isEnabled(),"Populated screen can be removed");int count=store.pageCount();clickDescription("Add desktop screen");await(()->store.pageCount()==count+1,"Add screen card did not create a desktop");int added=store.page;clickDescription("Remove "+store.pageName(added));await(()->store.pageCount()==count,"Empty-screen removal failed");
        clickDescription("Add desktop screen");added=store.page;clickDescription("Open "+store.pageName(added));await(()->field("desktopManager")==null,"Tapping a miniature did not open its desktop");pinch();await(()->field("desktopManager")!=null,"Pinch on empty desktop did not open management");
        main(()->invoke("onNewIntent",new Class[]{Intent.class},new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME)));check(store.page==store.homePage()&&store.pages.get(store.page).contains(wrong),"Home key did not return to the chosen screen");
        main(()->invoke("showFolder",new Class[]{LauncherStore.Item.class},wrong));await(()->find(v->v instanceof IconTile&&app.label.contentEquals(v.getContentDescription()))!=null,"Folder item missing");IconTile tile=(IconTile)find(v->v instanceof IconTile&&app.label.contentEquals(v.getContentDescription()));check(app.label.contentEquals(tile.label.getText())&&tile.label.getEllipsize()==null&&tile.label.getMaxLines()>1,"Folder menu still shortens long app names");
        int[] p=point(tile);time=SystemClock.uptimeMillis();pointer(time,0,p[0],p[1]);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);await(()->text("Move to folder")!=null,"Folder item hold menu has no Move to folder");pointer(time,1,p[0],p[1]);check(text("Add to folder").getTop()<text("Move to folder").getTop(),"Move to folder is not below Add to folder");click("Move to folder");check(text(wrong.label)==null,"Move destinations include the current folder");click(target.label);
        await(()->wrong.children.isEmpty()&&target.children.contains(app),"Moving an app left it in its original folder");check(target.children.get(0)==app&&target.children.get(0).id.equals(app.id),"Move replaced shortcut identity");capture("folder-move-complete-full-names");
        main(()->{LauncherStore.Item duplicate=new LauncherStore.Item(app.key,app.label);wrong.children.add(duplicate);int size=target.children.size();check(store.moveToFolder(duplicate,target)&&wrong.children.isEmpty()&&target.children.size()==size,"Move to a folder already containing the app duplicated it");LauncherStore.Item protectedApp=new LauncherStore.Item("builtin:calculator","Keep this source");wrong.children.add(protectedApp);for(int n=target.children.size();n<1000;n++)target.children.add(new LauncherStore.Item("test:"+n,"Item"));check(!store.moveToFolder(protectedApp,target)&&wrong.children.contains(protectedApp),"Full destination removed the source before checking capacity");target.children.subList(1,target.children.size()).clear();store.save();invoke("closePanel");});
    }
    private boolean dragging(){try{Object manager=field("desktopManager");Field f=DesktopManagerView.class.getDeclaredField("dragged");f.setAccessible(true);return manager!=null&&f.getInt(manager)>=0;}catch(Exception e){throw new AssertionError(e);}}
    private void pinch(){View desktop=(View)field("desktop");int[] pos=new int[2];main(()->desktop.getLocationOnScreen(pos));float x=pos[0]+desktop.getWidth()/2f,y=pos[1]+desktop.getHeight()*.6f;long t=SystemClock.uptimeMillis();pointer(t,0,x-100,y);multi(t,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),new float[]{x-100,x+100},y);multi(t,MotionEvent.ACTION_MOVE,new float[]{x-35,x+35},y);multi(t,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),new float[]{x-35,x+35},y);pointer(t,1,x-35,y);}
    private void multi(long t,int action,float[] x,float y){MotionEvent.PointerProperties[] properties=new MotionEvent.PointerProperties[2];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[2];for(int i=0;i<2;i++){properties[i]=new MotionEvent.PointerProperties();properties[i].id=i;properties[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=x[i];coords[i].y=y;coords[i].pressure=coords[i].size=1;}MotionEvent e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,2,properties,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);check(test.getUiAutomation().injectInputEvent(e,true),"Pinch input rejected");e.recycle();SystemClock.sleep(80);}
    private int[] point(View v){check(v!=null,"Input view missing");int[] p=new int[2];main(()->v.getLocationOnScreen(p));p[0]+=v.getWidth()/2;p[1]+=Math.min(v.getHeight()/2,Ui.dp(activity,45));return p;}
    private void pointer(long t,int action,float x,float y){MotionEvent e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(test.getUiAutomation().injectInputEvent(e,true),"Management input rejected");e.recycle();SystemClock.sleep(70);}
    private void click(String label){main(()->{View v=text(label);check(v!=null,"Missing menu item "+label);v.performClick();});SystemClock.sleep(300);}
    private void clickDescription(String label){main(()->{View v=find(w->android.text.TextUtils.equals(label,w.getContentDescription()));check(v!=null&&v.isEnabled(),"Missing action "+label);v.performClick();});SystemClock.sleep(350);}
    private View text(String text){return find(v->v instanceof TextView&&text.contentEquals(((TextView)v).getText()));}private View findTag(String tag){return find(v->tag.equals(v.getTag()));}
    private View find(java.util.function.Predicate<View> match){return find(activity.getWindow().getDecorView(),match);}private View find(View v,java.util.function.Predicate<View> match){if(v.getVisibility()!=View.VISIBLE)return null;if(match.test(v))return v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){View child=find(((android.view.ViewGroup)v).getChildAt(i),match);if(child!=null)return child;}return null;}
    private Object field(String name){try{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object invoke(String name){return invoke(name,new Class[0]);}private Object invoke(String name,Class[] types,Object...args){try{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private void main(Runnable r){test.runOnMainSync(r);}private void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}private void await(BooleanSupplier condition,String message){long end=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<end){java.util.concurrent.atomic.AtomicBoolean result=new java.util.concurrent.atomic.AtomicBoolean();main(()->result.set(condition.getAsBoolean()));if(result.get())return;SystemClock.sleep(100);}throw new AssertionError(message);}
    private void capture(String name)throws Exception{SystemClock.sleep(800);android.graphics.Bitmap b=test.getUiAutomation().takeScreenshot();java.io.File dir=output==null?new java.io.File(activity.getExternalFilesDir(null),"verification"):new java.io.File(output);dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
}
